import{_ as a,o as s,c as n}from"./chunks/framework.D1Ss-Xl7.js";const h=JSON.parse(`{"title":"Page 38 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"38","title":"Page 38 | Home","prev":"/page/37/","next":"/page/39/","posts":[{"title":"Archlinux下使用airbase和dhcpd建立虚拟AP","url":"/posts/2013-08-26-archlinux-airbase-create-fakeap/","date":"2013-08-26 21:29","tags":["linux","airbase"],"html":"<p>Linux 下的 wicd 本身自带一个创建 Ad-Hoc network 功能的,但是这个功能太不实用了, 首先,Ad-Hoc 只能把笔记本的无线通过有线进行共享,而且 Ad-Hoc 网络无法被安卓原生系统识别,CM 倒是可以用.hostapd 也是一样.只能把有线网络通过无线进行共享.\\n但是我经常是电脑连接 WIFI,并且想把 WIFI 共享给手机进行使用,于是我又开始折腾了 &gt;_&gt;</p>\\n<h2 id=\\"首先安装所需要的软件\\" tabindex=\\"-1\\">首先安装所需要的软件 <a class=\\"header-anchor\\" href=\\"#首先安装所需要的软件\\" aria-label=\\"Permalink to &quot;首先安装所需要的软件&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>net-tools</span></span>\\n<span class=\\"line\\"><span>iptables</span></span>\\n<span class=\\"line\\"><span>aircrack-ng</span></span>\\n<span class=\\"line\\"><span>dhcpd</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><h2 id=\\"然后启动虚拟-ap\\" tabindex=\\"-1\\">然后启动虚拟 AP <a class=\\"header-anchor\\" href=\\"#然后启动虚拟-ap\\" aria-label=\\"Permalink to &quot;然后启动虚拟 AP&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">airmon-ng</span><span style=\\"color:#032F62\\"> start</span><span style=\\"color:#032F62\\"> wlp5s0</span><span style=\\"color:#6A737D\\"> # 启动无线网卡的monitor模式 wlp5s0是我网卡的设备名 这时候会看到输出 monitor mode enabled on mon0 mon0便是虚拟出来的一个网卡设备</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">airbase-ng</span><span style=\\"color:#005CC5\\"> -e</span><span style=\\"color:#032F62\\"> FreeWifi</span><span style=\\"color:#005CC5\\">  -v</span><span style=\\"color:#032F62\\"> mon0</span><span style=\\"color:#24292E\\"> &#x26; </span><span style=\\"color:#6A737D\\"># 在mon0设备上创建Fake AP -e选项是设置SSID名字 -v是启动DEBUG模式 最后是设备名字,想进行后台运行请按Ctrl+D</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><h2 id=\\"激活-tap-insterface-并添加路由表\\" tabindex=\\"-1\\">激活 tap insterface 并添加路由表 <a class=\\"header-anchor\\" href=\\"#激活-tap-insterface-并添加路由表\\" aria-label=\\"Permalink to &quot;激活 tap insterface 并添加路由表&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>执行上面的名字之后会输出 Created tap interface at0\\n然后执行下面的命令</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">ifconfig</span><span style=\\"color:#032F62\\"> at0</span><span style=\\"color:#032F62\\"> up</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">ifconfig</span><span style=\\"color:#032F62\\"> at0</span><span style=\\"color:#005CC5\\"> 10.0.0.254</span><span style=\\"color:#032F62\\"> netmask</span><span style=\\"color:#005CC5\\"> 255.255.255.0</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">route</span><span style=\\"color:#032F62\\"> add</span><span style=\\"color:#005CC5\\"> -net</span><span style=\\"color:#005CC5\\"> 10.0.0.0</span><span style=\\"color:#032F62\\"> netmask</span><span style=\\"color:#005CC5\\"> 255.255.255.0</span><span style=\\"color:#032F62\\"> gw</span><span style=\\"color:#005CC5\\"> 10.0.0.254</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><h2 id=\\"设置-iptables\\" tabindex=\\"-1\\">设置 iptables <a class=\\"header-anchor\\" href=\\"#设置-iptables\\" aria-label=\\"Permalink to &quot;设置 iptables&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">iptables</span><span style=\\"color:#005CC5\\"> --flush</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">iptables</span><span style=\\"color:#005CC5\\"> --table</span><span style=\\"color:#032F62\\"> nat</span><span style=\\"color:#005CC5\\"> --flush</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">iptables</span><span style=\\"color:#005CC5\\"> --delete-chain</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">iptables</span><span style=\\"color:#005CC5\\"> --table</span><span style=\\"color:#032F62\\"> nat</span><span style=\\"color:#005CC5\\"> --delete-chain</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">iptables</span><span style=\\"color:#005CC5\\"> -P</span><span style=\\"color:#032F62\\"> FORWARD</span><span style=\\"color:#032F62\\"> ACCEPT</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">iptables</span><span style=\\"color:#005CC5\\"> -t</span><span style=\\"color:#032F62\\"> nat</span><span style=\\"color:#005CC5\\"> -A</span><span style=\\"color:#032F62\\"> POSTROUTING</span><span style=\\"color:#005CC5\\"> -o</span><span style=\\"color:#032F62\\"> wlp5s0</span><span style=\\"color:#005CC5\\"> -j</span><span style=\\"color:#032F62\\"> MASQUERADE</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">//这里wlp5s0是我额外要连接到互联网的网卡设备名</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br></div></div><h2 id=\\"配置-dns-服务器\\" tabindex=\\"-1\\">配置 DNS 服务器 <a class=\\"header-anchor\\" href=\\"#配置-dns-服务器\\" aria-label=\\"Permalink to &quot;配置 DNS 服务器&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>没有 DNS 服务器即使能搜到 AP 也无法连接,因为获取不到 IP 地址.\\n首先列出 <code>dhcpd.conf</code> 的内容</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">ddns-update-style</span><span style=\\"color:#032F62\\"> none</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">default-lease-time</span><span style=\\"color:#005CC5\\"> 600</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">max-lease-time</span><span style=\\"color:#005CC5\\"> 7200</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">authoritative</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">subnet</span><span style=\\"color:#005CC5\\"> 10.0.0.0</span><span style=\\"color:#032F62\\"> netmask</span><span style=\\"color:#005CC5\\"> 255.255.255.0</span><span style=\\"color:#032F62\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">option</span><span style=\\"color:#032F62\\"> subnet-mask</span><span style=\\"color:#005CC5\\"> 255.255.255.0</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">option</span><span style=\\"color:#032F62\\"> broadcast-address</span><span style=\\"color:#005CC5\\"> 10.0.0.255</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">option</span><span style=\\"color:#032F62\\"> routers</span><span style=\\"color:#005CC5\\"> 10.0.0.254</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">option</span><span style=\\"color:#032F62\\"> domain-name-servers</span><span style=\\"color:#005CC5\\"> 114.114.114.114</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">range</span><span style=\\"color:#005CC5\\"> 10.0.0.1</span><span style=\\"color:#005CC5\\"> 10.0.0.140</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br></div></div><p>然后执行下面的命令</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#005CC5\\">echo</span><span style=\\"color:#D73A49\\"> ></span><span style=\\"color:#032F62\\"> '/var/lib/dhcp/dhcpd.leases'</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">dhcpd</span><span style=\\"color:#005CC5\\"> -d</span><span style=\\"color:#005CC5\\"> -f</span><span style=\\"color:#005CC5\\"> -cf</span><span style=\\"color:#032F62\\"> dhcpd.conf</span><span style=\\"color:#032F62\\"> at0</span><span style=\\"color:#24292E\\"> &#x26;</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><h2 id=\\"最后启用-ip-forwarding\\" tabindex=\\"-1\\">最后启用 IP forwarding <a class=\\"header-anchor\\" href=\\"#最后启用-ip-forwarding\\" aria-label=\\"Permalink to &quot;最后启用 IP forwarding&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#005CC5\\">echo</span><span style=\\"color:#032F62\\"> \\"1\\"</span><span style=\\"color:#D73A49\\"> ></span><span style=\\"color:#032F62\\"> /proc/sys/net/ipv4/ip_forward</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"写在最后\\" tabindex=\\"-1\\">写在最后 <a class=\\"header-anchor\\" href=\\"#写在最后\\" aria-label=\\"Permalink to &quot;写在最后&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>虽然能创建虚拟 AP,但是安卓原生系统连接获取到 IP 一段时间后又会自动掉线,原因不明,希望知道的菊苣能告诉咱一声~</p>\\n"},{"title":"Archlinux下Galaxy Nexus刷机并root","url":"/posts/2013-07-20-archlinux-flash-android/","date":"2013-07-20 14:12","tags":["linux","android"],"html":"<p>安卓本来就是 Linux 衍生的,所以必然可以用 Linux 系统进行刷机,而且效果比 Win 还要好.不需要安装驱动,只需要安装 adb 和 fastboot 即可.</p>\\n<h2 id=\\"安装相关依赖\\" tabindex=\\"-1\\">安装相关依赖 <a class=\\"header-anchor\\" href=\\"#安装相关依赖\\" aria-label=\\"Permalink to &quot;安装相关依赖&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先通过 AUR 源安装[android-sdk](<a href=\\"https://aur.archlinux.org/packages/android-sdk/%E5%92%8C%5Bandroid-sdk-platform-tools%5D(https://aur.archlinux.org/packages/android-sdk-platform-tools/)%E7%9B%B8%E5%85%B3%E7%9A%84wiki%E5%9C%A8\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://aur.archlinux.org/packages/android-sdk/和[android-sdk-platform-tools](https://aur.archlinux.org/packages/android-sdk-platform-tools/)相关的wiki在</a> <a href=\\"https://wiki.archlinux.org/index.php/Android\\" target=\\"_blank\\" rel=\\"noreferrer\\">这里</a></p>\\n<p>通过 <code>yaourt -Ql android-sdk-platform-tools</code> 可以发现 adb 和 fastboot 都安装在<code>/opt/android-sdk/platform-tools</code> 目录下,但是 PATH 环境变量没有这个值,所以无法在终端里直接调用必须先设置 PATH 变量 <code>export PATH=&quot;\${PATH}:/opt/android-sdk/platform-tools&quot;</code>在 .xinitrc 里面添加这句就可以使 X 下的终端 PATH 环境变量被添加.也可以直接执行,当终端关闭时 PATH 变量的设置也失效.</p>\\n<h2 id=\\"配置-adb\\" tabindex=\\"-1\\">配置 ADB <a class=\\"header-anchor\\" href=\\"#配置-adb\\" aria-label=\\"Permalink to &quot;配置 ADB&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>前面提供的 wiki 已经很详细的讲述如何进行<a href=\\"https://wiki.archlinux.org/index.php/Android#Connecting_to_a_real_device_-_Android_Debug_Bridge_.28ADB.29\\" target=\\"_blank\\" rel=\\"noreferrer\\">ADB 的配置了</a></p>\\n<h2 id=\\"测试-fastboot\\" tabindex=\\"-1\\">测试 FASTBOOT <a class=\\"header-anchor\\" href=\\"#测试-fastboot\\" aria-label=\\"Permalink to &quot;测试 FASTBOOT&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>fastboot 模式（上下音量键和开机键一起按）,可以看到一个大大的 Start 画面,这就是进入了 fastboot.或者使用命令<code>adb reboot bootloader</code>。此时把手机用 USB 连入电脑. 在终端里面输入 fastboot devices 如果提示 no permission 即是普通用户没有权限。这时候就需要切换到 root 用户进行执行.如果输入一串数字.则说明系统识别到了你的手机.</p>\\n<h2 id=\\"刷机开始\\" tabindex=\\"-1\\">刷机开始 <a class=\\"header-anchor\\" href=\\"#刷机开始\\" aria-label=\\"Permalink to &quot;刷机开始&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先要下载<a href=\\"https://developers.google.com/android/nexus/images\\" target=\\"_blank\\" rel=\\"noreferrer\\">固件</a>下载下来的 tgz 文件解压即可看到有个 flash-all.sh 的脚本。首先 <code>chmod +x flash-all.sh</code> 赋予脚本执行权限，然后执行这个脚本即可,如果有大量输出则说明刷机正常进行中.</p>\\n<h2 id=\\"后续-root\\" tabindex=\\"-1\\">后续 ROOT <a class=\\"header-anchor\\" href=\\"#后续-root\\" aria-label=\\"Permalink to &quot;后续 ROOT&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>ROOT 的话首先需要刷 recovery,我们先下载<a href=\\"http://www.clockworkmod.com/rommanager\\" target=\\"_blank\\" rel=\\"noreferrer\\">recovery</a>找到自己型号的 recovery 进行下载,我的是 recovery-clockwork-touch-6.0.3.3-maguro.img，touch 代表的是是否支持触摸.否则只能用音量键和开机键进行选择和确定.然后下载 superSU 的 ZIP 压缩包,目前版本是<a href=\\"http://download.chainfire.eu/339/SuperSU/UPDATE-SuperSU-v1.41.zip?retrieve_file=1\\" target=\\"_blank\\" rel=\\"noreferrer\\">1.41</a> ,ZIP 格式不要解压.放入 SD 卡中.<code>adb push UPDATE-SuperSU-v1.41.zip /sdcard/</code>将手机关机进入 fastboot 模式,应该先解锁, <code>fastboot oem unlock</code>然后刷入 recovery <code>fastboot flash recovery recovery-clockwork-touch-6.0.3.3-maguro.img</code>按下音量键调至 recovery，按开机键进入，手机会自动重启进入 recovery。choose zip from SDcard，然后依次进入，最终选择 UPDATE-SuperSU-v1.41.zip，确认安装.</p>\\n<p>注：如果提示是否清除 recovery flash，请选 No，否则下次推送时无法进行 OTA 更新.安装完成后依次返回.这个步骤不会影响 OTA 更新,并且 OTA 更新之后会自动解决 ROOT 的问题,无需再次 ROOT.</p>\\n<h2 id=\\"adb-小技巧\\" tabindex=\\"-1\\">ADB 小技巧 <a class=\\"header-anchor\\" href=\\"#adb-小技巧\\" aria-label=\\"Permalink to &quot;ADB 小技巧&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>刷机之后需要一大堆 APK 软件安装怎么办 adb 本身只有单个 APK 安装的功能，通过 <code>ls -1 *.apk | xargs -l adb install</code> 这个命令可以批量的把一个文件夹下的所以 APK 安装上去,而且还是静默安装. 不过首先要打开 ADB 调试才行.</p>\\n<h2 id=\\"手机-mtp-连接-linux-电脑\\" tabindex=\\"-1\\">手机 MTP 连接 Linux 电脑 <a class=\\"header-anchor\\" href=\\"#手机-mtp-连接-linux-电脑\\" aria-label=\\"Permalink to &quot;手机 MTP 连接 Linux 电脑&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>MTP 是微软发明的东西....当然不好用\\n目前有两种解决方案一种是 GMTP,速度较慢,因为第一次和之后所有操作之后都会全部索引一遍文件列表.第二种是 gvfs-mtp 结合 thunar 使用,可以自动挂载,如果无法挂载可以使用 <code>lsusb</code> 命令.</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>Bus 001 Device 117: ID 04e8:6860 Samsung Electronics Co., Ltd GT-I9100 Phone [Galaxy S II], GT-I9300 Phone [Galaxy S III], GT-P7500 [Galaxy Tab 10.1]</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>可以看到我的设备号,然后在地址栏里面输入 <code>mtp://[usb:001,117]/</code>。第一个数字是 Bus 号,第二个数字是设备号.</p>\\n"},{"title":"Archlinux下终端进行代理的解决方案","url":"/posts/2013-07-18-archlinux-terminal-proxy/","date":"2013-07-18 22:05","tags":["linux","proxy"],"html":"<p>Linux 下软件安装基本都是在终端下进行的....<br>\\n虽说安装软件基本上选对源就没有无法安装的,但是 Archlinux 下的 yaourt 安装就是社区打包的软件了.<br>\\n软件来源各种各样,有的是 Google code 上的,有的是 GitHub 上的,有的就是 sourceforge 上的了.<br>\\n但是在中国的大环境下不能保证上面网站的正常访问 QAQ Google 的话有 hosts 的情况下基本上是\\n把 http 修改成 https 就可以下载了,其余两个就只能代理进行下载软件并安装了.</p>\\n<h2 id=\\"代理\\" tabindex=\\"-1\\">代理 <a class=\\"header-anchor\\" href=\\"#代理\\" aria-label=\\"Permalink to &quot;代理&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先科学上网的话就需要代理,SSH 这样进行端口监听的比较不错.VPN 是全局代理就不用讲述了.\\n不过 VPN 也可以走路由表进行部分代理(不在本文讨论范围之内)SSH 的话在 Linux 下就是简单的一句 <code>ssh -NfD 127.0.0.1:7070 user@server</code><br>\\n因为 SSH 不是 HTTP 代理,所以需要转发,如果是纯 HTTP 代理的话直接配置环境变量即可.\\n前面写的是本机代理的端口,后面是服务器的用户名和服务器 IP 地址.</p>\\n<h2 id=\\"转发\\" tabindex=\\"-1\\">转发 <a class=\\"header-anchor\\" href=\\"#转发\\" aria-label=\\"Permalink to &quot;转发&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>SSH 是 SOCKET5 代理,但是下载的话基本上就是 HTTP 代理怎么转发呢? 这里就需要一个软件叫做<a href=\\"https://wiki.archlinux.org/index.php/Privoxy\\" target=\\"_blank\\" rel=\\"noreferrer\\">Privoxy</a>\\nPrivoxy 可以把 SOCKET5 转 HTTP 代理,\\n首先安装它 <code>sudo pacman -S privoxy</code> 然后进行配置 <code>sudo vim /etc/privoxy/config</code>在配置文件里面添加 <code>forward-socks5 / 127.0.0.1:7070 .</code>\\n注意后面有个点,容易忽略. 这个是转入的 SOCKET5 代理,指的是 SSH 的代理监听的端口号.\\n配置文件里面有句话是 <code>listen-address 127.0.0.1:8118</code> 这个是转发出去的 HTTP 代理的端口号.\\n这样写好之后, 启动服务 <code>sudo systemctl start privoxy.service</code></p>\\n<h2 id=\\"配置环境变量\\" tabindex=\\"-1\\">配置环境变量 <a class=\\"header-anchor\\" href=\\"#配置环境变量\\" aria-label=\\"Permalink to &quot;配置环境变量&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>转发实现之后就可以应用在终端里面了,\\n在终端里面输入</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#24292E\\"> https_proxy</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">127.0.0.1:8118</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#24292E\\"> http_proxy</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">127.0.0.1:8118</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><p>这样就完成代理的设置了.</p>\\n"}]},"relativePath":"page/38/index.md","filePath":"page/[page].md"}`),e={name:"page/38/index.md"};function o(l,p,r,t,c,i){return s(),n("div")}const b=a(e,[["render",o]]);export{h as __pageData,b as default};
